const body = $input.first().json.body || {};
const message = body.message || {};
const isAssistantRequest = message.type === 'assistant-request';

// VAPI's docs do not pin down one path for the caller's number, so check the
// documented candidates in order.
const raw = String(
  message.call?.customer?.number ||
  message.customer?.number ||
  message.call?.from?.phoneNumber ||
  ''
).trim();

// Normalize US phone to E.164 (same rules as lookup-caller's Parse Envelope)
let phone = raw;
let error = '';
if (phone) {
  const digits = phone.replace(/\D/g, '');
  if (digits.length === 10) phone = '+1' + digits;
  else if (digits.length === 11 && digits[0] === '1') phone = '+' + digits;
  else if (phone.startsWith('+') && digits.length >= 10) phone = '+' + digits;
  else { error = 'invalid_phone'; phone = ''; }
} else {
  error = 'no_phone';   // withheld / anonymous caller ID
}

return [{
  json: {
    is_assistant_request: isAssistantRequest,
    phone_number: phone,
    // phone_digits strips '+', matching the customers.phone_digits generated column.
    // '0' can never match a row, so a missing number is a guaranteed no-match
    // instead of an unfiltered query.
    phone_digits: phone ? phone.replace('+', '') : '0',
    error
  }
}];

const env = $('Parse Assistant Request').first().json;
// A failed or timed-out lookup arrives here as an item without an id, and is
// treated exactly like "no match".
const rows = $input.all().map(i => i.json).filter(r => r && r.id);

// Exactly one customer on this number = recognised. Zero, or several people
// sharing a number, = unknown (we will not guess who is calling).
const known = env.is_assistant_request === true && rows.length === 1;
const r = known ? rows[0] : {};

return [{
  json: {
    caller_known: known,
    first_name: r.first_name || '',
    claim_number: r.claim_number || '',
    claim_status: r.claim_status || '',
    phone_number: env.phone_number,
    // only look up call history for a recognised caller
    phone_digits: known ? env.phone_digits : '0'
  }
}];

// Replaced from .env by scripts/deploy-n8n.sh (deploy fails if it is not set).
const ASSISTANT_ID = '__VAPI_ASSISTANT_ID__';

const env = $('Parse Assistant Request').first().json;
if (!env.is_assistant_request) {
  return [{ json: {} }];   // not our event: acknowledge and do nothing
}

const c = $('Pick Customer').first().json;
const last = $input.all().map(i => i.json)
  .filter(r => r && r.timestamp && typeof r.summary === 'string')
  .sort((a, b) => String(b.timestamp).localeCompare(String(a.timestamp)))[0] || {};

// A name is spoken aloud in the greeting: only letters, spaces, hyphens, apostrophes.
const cleanName = String(c.first_name || '').trim();
const nameOk = /^[\p{L}][\p{L} '\-]{0,39}$/u.test(cleanName);
const known = c.caller_known === true && nameOk;
const sentiments = ['positive', 'neutral', 'negative'];

// Values are strings on purpose: how VAPI renders booleans / nulls in a prompt
// template is not documented.
const variableValues = {
  callerKnown: known ? 'true' : 'false',
  firstName: known ? cleanName : '',
  claimNumber: known ? String(c.claim_number || '') : '',
  claimStatus: known ? String(c.claim_status || '') : '',
  lastCallSummary: known ? String(last.summary || '').replace(/\s+/g, ' ').trim().substring(0, 300) : '',
  lastCallSentiment: (known && sentiments.includes(last.sentiment)) ? last.sentiment : '',
  callerNumber: known ? String(c.phone_number || '') : ''
};

const assistantOverrides = { variableValues };
if (known) {
  // Unknown callers keep the assistant's own firstMessage, i.e. today's greeting.
  assistantOverrides.firstMessage = 'Thank you for calling Observe Insurance, ' + cleanName +
    '. This call may be monitored for quality assurance. My name is Sarah. Before I pull up your account, could you please verify your date of birth?';
}

return [{ json: { assistantId: ASSISTANT_ID, assistantOverrides } }];
